const fs = require\('fs'\);
const data = JSON.parse\(fs.readFileSync\('b0yvqiqk9.txt', 'utf-8'\)\);

const pages = [];
const databases = [];

for \(const item of data.results || []\) {
  const objType = item.object;
  const id = item.id;
  const parent = item.parent || {};
  const cover = item.cover;
  const icon = item.icon;

  let title = '';

  if \(objType === 'page'\) {
    const props = item.properties || {};
    for \(const [key, val] of Object.entries\(props\)\) {
      if \(val.type === 'title'\) {
        title = \(val.title || []\).map\(t => t.plain_text || ''\).join\(''\);
        break;
      }
    }
    pages.push\({ id, title: title.trim\(\), parent, cover, icon }\);
  } else if \(objType === 'database'\) {
    title = \(item.title || []\).map\(t => t.plain_text || ''\).join\(''\);
    databases.push\({ id, title: title.trim\(\), parent, cover, icon }\);
  }
}

console.log\('=== PAGES \(' + pages.length + '\) ==='\);
for \(const p of pages\) {
  console.log\('  Title: ' + \(p.title || '\(untitled\)'\)\);
  console.log\('  ID: ' + p.id\);
  if \(p.parent.type === 'database_id'\) console.log\('  Parent DB: ' + p.parent.database_id\);
  else if \(p.parent.type === 'page_id'\) console.log\('  Parent Page: ' + p.parent.page_id\);
  else if \(p.parent.type === 'workspace'\) console.log\('  Parent: workspace \(top-level\)'\);
  if \(p.icon\) {
    if \(p.icon.type === 'emoji'\) console.log\('  Icon: ' + p.icon.emoji\);
    else if \(p.icon.type === 'external'\) console.log\('  Icon: ' + p.icon.external.url\);
  }
  if \(p.cover\) {
    if \(p.cover.type === 'external'\) console.log\('  Cover: ' + p.cover.external.url\);
    else if \(p.cover.type === 'file'\) console.log\('  Cover: \(uploaded file\)'\);
  }
  console.log\(\);
}

console.log\('=== DATABASES \(' + databases.length + '\) ==='\);
for \(const d of databases\) {
  console.log\('  Title: ' + \(d.title || '\(untitled\)'\)\);
  console.log\('  ID: ' + d.id\);
  if \(d.parent.type === 'database_id'\) console.log\('  Parent DB: ' + d.parent.database_id\);
  else if \(d.parent.type === 'page_id'\) console.log\('  Parent Page: ' + d.parent.page_id\);
  else if \(d.parent.type === 'workspace'\) console.log\('  Parent: workspace \(top-level\)'\);
  if \(d.icon\) {
    if \(d.icon.type === 'emoji'\) console.log\('  Icon: ' + d.icon.emoji\);
    else if \(d.icon.type === 'external'\) console.log\('  Icon: ' + d.icon.external.url\);
  }
  if \(d.cover\) {
    if \(d.cover.type === 'external'\) console.log\('  Cover: ' + d.cover.external.url\);
  }
  console.log\(\);
}
")

