const fs = require\('fs'\);
const data = JSON.parse\(fs.readFileSync\('b0yvqiqk9.txt', 'utf-8'\)\);

// Collect unique parent DB/page IDs
const parentDBs = new Set\(\);
const parentPages = new Set\(\);
const pagesWithNoParentInfo = [];

for \(const item of data.results || []\) {
  const parent = item.parent || {};
  if \(parent.type === 'database_id'\) parentDBs.add\(parent.database_id\);
  else if \(parent.type === 'page_id'\) parentPages.add\(parent.page_id\);
  else if \(!parent.type || parent.type === 'workspace'\) {
    const props = item.properties || {};
    let title = '';
    for \(const [k,v] of Object.entries\(props\)\) {
      if \(v.type === 'title'\) { title = \(v.title||[]\).map\(t=>t.plain_text\).join\(''\); break; }
    }
    pagesWithNoParentInfo.push\({ id: item.id, title: title.trim\(\) }\);
  }
}

console.log\('=== Parent Databases referenced ==='\);
for \(const id of parentDBs\) console.log\('  ' + id\);
console.log\(\);
console.log\('=== Parent Pages referenced ==='\);
for \(const id of parentPages\) console.log\('  ' + id\);
console.log\(\);
console.log\('=== Pages with no explicit parent \(workspace-level or unspecified\) ==='\);
for \(const p of pagesWithNoParentInfo\) console.log\('  ' + p.id + ' -> ' + \(p.title || '\(untitled\)'\)\);

// Check statuses for each page
console.log\(\);
console.log\('=== Page Statuses ==='\);
for \(const item of data.results || []\) {
  if \(item.object !== 'page'\) continue;
  const props = item.properties || {};
  let title = '';
  for \(const [k,v] of Object.entries\(props\)\) {
    if \(v.type === 'title'\) { title = \(v.title||[]\).map\(t=>t.plain_text\).join\(''\); break; }
  }
  const status = props['상태']?.status?.name || '';
  const scale = props['척도']?.status?.name || '';
  const date = props['날짜']?.date?.start || '';
  if \(status || scale || date\) {
    console.log\('  ' + title.trim\(\).substring\(0,40\) + ' | 상태=' + status + ' | 척도=' + scale + ' | 날짜=' + date\);
  }
}

console.log\(\);
console.log\('has_more:', data.has_more\);
console.log\('next_cursor:', data.next_cursor\);
")

